import styles from './Header.module.css';

import logo from 'asset/hm_logo.png';
import { useLocation, useNavigate } from 'react-router-dom';

interface HeaderProps {
    /** 스크롤에 따른 헤더 색상 */
    color: boolean;
}

function Header({ color }: HeaderProps) {

    const navigate = useNavigate();
    const { pathname } = useLocation();

    return(
        <div className={color ? [styles["header"], styles["colored"]].join(" "): styles["header"]}>
            <div onClick={() => navigate("/")}>
                <img src={logo} alt="logo"></img>
            </div>
            <ul>
                <li onClick={ () => navigate("/experience")} 
                    className={pathname === "/experience" ? styles["active"] : ''}>EXPERIENCE</li>
                <li onClick={ () => navigate("/info")} 
                    className={pathname === "/info" ? styles["active"] : ''}>INFO</li>
            </ul>
        </div>
    )
};

export default Header;