import { useLocation, useParams } from 'react-router';
import styles from './Detail.module.css';

import { exhibit } from "mainData";
import { CardType, LocationState } from "types";

const Detail = () =>{
    
    const { id } = useParams<{ id: string }>(); // /detail/:id
    const location = useLocation();

    // location.state 타입 안전하게 캐스팅
  const { state } = (location.state as LocationState) || { state: 0 };

  // exhibit에서 해당 카드 찾기
  const card: CardType | undefined = exhibit.find((item) => item.key === id);

  if (!card) {
    return <div>존재하지 않는 페이지입니다.</div>;
  }
    
    return(
        <div className={styles["Detail"]}>
            <div>
                <img src={card.mainImage} alt={card.mainImage}></img>
            </div>
            <div className={styles["desc"]}>
                <div>
                    <h1 className={styles["title_en"]}>
                        {card.titleEn[0]} <br/>
                        {card.titleEn[1]}
                    </h1>
                    <h3>
                        {card.titleKo}
                    </h3>
                </div>
                <div>
                    <div className={styles["etc"]}>
                        {card.etc.map((item,idx) =>{
                            return <p key={idx}>{item}</p>
                        })}
                    </div>
                    <div className={styles["icons"]}>
                        {card.icon.slice(0).reverse().map((item,idx) =>{
                            return <div key={idx}>
                                <img src={item} alt="아이콘"></img>
                            </div>
                        })}
                    </div>
                </div>
            </div>
            <div id="test" className={styles["images"]}>
            {card.images.map((item, idx) => {
            if (Array.isArray(item)) {
                // 이미지가 2장일 때
                return (
                <div key={idx}>
                    {item.map((img, subIdx) => (
                    <img
                        key={subIdx}
                        style={{ width: "49.5%" }}
                        src={img}
                        alt={card.titleKo}
                    />
                    ))}
                </div>
                );
            } else {
                // 이미지가 1장일 때
                return (
                <div
                    key={idx}
                    style={
                    item.includes("right")
                        ? { justifyContent: "right" }
                        : item.includes("left")
                        ? { justifyContent: "start" }
                        : { justifyContent: "space-between" }
                    }
                >
                <img
                  style={
                    item.includes("right") || item.includes("left")
                      ? { width: "50%" }
                      : { width: "100%" }
                  }
                  src={item}
                  alt={card.titleKo}
                />
              </div>
            );
          }
        })}
      </div>
    </div>
  );
};

export default Detail;