import React, { useEffect, useRef } from "react";
import styles from "./Info.module.css";
import { intro, infoSections, projectsA, projectsB, projectsC } from "data";
import { InfoItem, Project} from "types";

type InfoOrProject =
  | { type: "info"; page: 1; data: InfoItem }
  | { type: "project"; page: 2; data: Project };

const Info: React.FC = () => {
  const outerDivRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const wheelHandler = (e: WheelEvent) => {
      e.preventDefault();
      if (!outerDivRef.current) return;

      const { deltaY } = e;
      const { scrollTop } = outerDivRef.current;
      const pageHeight = window.innerHeight;

      if (deltaY > 0) {
        // scroll down
        if (scrollTop >= 0 && scrollTop < pageHeight) {
          outerDivRef.current.scrollTo({
            top: pageHeight,
            left: 0,
            behavior: "smooth",
          });
        } else if (scrollTop >= pageHeight && scrollTop < pageHeight * 2) {
          outerDivRef.current.scrollTo({
            top: pageHeight * 2,
            left: 0,
            behavior: "smooth",
          });
        }
      } else {
        // scroll up
        if (scrollTop >= 0 && scrollTop < pageHeight) {
          outerDivRef.current.scrollTo({ top: 0, left: 0, behavior: "smooth" });
        } else if (scrollTop >= pageHeight && scrollTop < pageHeight * 2) {
          outerDivRef.current.scrollTo({ top: 0, left: 0, behavior: "smooth" });
        }
      }
    };

    const current = outerDivRef.current;
    current?.addEventListener("wheel", wheelHandler, { passive: false });

    return () => {
      current?.removeEventListener("wheel", wheelHandler);
    };
  }, []);

  // combinedData 배열 생성 (page 구분)
const combinedData: InfoOrProject[] = [
  ...infoSections.map((item) => ({ type: "info" as const, page: 1 as const, data: item })),
  ...projectsA.map((item) => ({ type: "project" as const, page: 2 as const, data: item })),
  ...projectsB.map((item) => ({ type: "project" as const, page: 2 as const, data: item })),
  ...projectsC.map((item) => ({ type: "project" as const, page: 2 as const, data: item })),
];

// 타입 가드 함수
function isPage1Info(
    item: InfoOrProject
  ): item is Extract<InfoOrProject, { page: 1; type: "info" }> {
    return item.page === 1 && item.type === "info";
}

function isPage2Project(
    item: InfoOrProject
  ): item is Extract<InfoOrProject, { page: 2; type: "project" }> {
    return item.page === 2 && item.type === "project";
}

// 필터링 후 데이터 추출
const page1Data = combinedData.filter(isPage1Info).map((item) => item.data);
const page2Data = combinedData.filter(isPage2Project).map((item) => item.data);

  return (
    <div ref={outerDivRef} className={styles["Info"]}>
      {/* page 1 */}
      <div className={[styles["inner"], styles["top"]].join(" ")}>
        {/* 왼쪽 영역 */}
        <div className={styles["desc"]}>
          <div className={styles["goal"]}>
            {intro.goal.split("\n").map((line, idx) => (
              <span key={idx}>
                {line}
                <br />
              </span>
            ))}
          </div>
          <div className={styles["contact"]}>
            <div>
              <div className={styles["stress"]}>{intro.contact.name}</div>
              {intro.contact.birth}
            </div>
            <br />
            <div>
              M :&nbsp;&nbsp;&nbsp;{intro.contact.mobile}
              <br />
              E :&nbsp;&nbsp;&nbsp;{intro.contact.email}
            </div>
          </div>
        </div>

        {/* 오른쪽 영역 (infoSections) */}
        <div className={styles["skill"]}>
          {page1Data.map((section) => (
            <div key={section.title} className={styles["container"]}>
              <div className={styles["heading"]}>{section.title}</div>
              {section.entries.map((entry) => (
                <div key={entry.name} className={styles["self-wrapper"]}>
                  <div>{entry.name}</div>
                  <div className={styles["sub"]}>{entry.date}</div>
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>

      {/* page 2 */}
      <div className={[styles["inner"], styles["bottom"]].join(" ")}>
        <h3>프로젝트 경력</h3>
        <div className={styles["wrapper"]}>
          {page2Data.map((project) => (
            <div key={project.company} className={styles["timeline"]}>
              <h4>{project.company}</h4>
              <h5>{project.period}</h5>
              <div className={styles["works-wrapper"]}>
                {project.work.map((wo, i) => (
                  <div key={i} className={styles["works"]}>
                    <p>{wo.per}</p>
                    <p>{wo.title}</p>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Info;