import styles from './Cards.module.css';

import { useNavigate } from 'react-router';

import { exhibit } from "mainData";
import { CardType, PageState } from "types";

interface CardProps {
  pageState: PageState;
}

export default function Cards({ pageState }: CardProps) {


  // exhibit가 CardType[] 타입이라고 명시
  const newList =
    pageState === 0
      ? exhibit
      : exhibit.filter((item) => item.state === pageState);

  const navigate = useNavigate();


  // 각 카드 호출
  function getProjectCard(Card: CardType) {
    
    return (
      <div className={styles["card_active"]} 
        key={Card.key} 
        onClick={() => navigate(`/detail/${Card.key}`, { state: Card.state })}>
          <div className={styles["image__wrapper"]}>
            <img src={Card.mainImage} className={styles["card__image"]} alt='' />
          </div>
          <div className={styles["card_title"]}>
            <p>{Card.desc[0]}</p>
            <p className={styles["size_down"]}>{Card.desc[1]}</p>
          </div>
      </div>
    );
  };

  return (
    <div className={styles["box"]} >
      <ul className={styles["cards"]}>
        {newList
          .slice(0)
          .reverse()
          .map((item) => getProjectCard(item))}
      </ul>
    </div>
  );
}