import { useState } from "react";
import styles from "./Experience.module.css";

import Cards from "../cards/Cards";
import { PageState } from "types";

const division = [
    { ko: "전체", en: "all" },
    { ko: "박물관", en: "museum" },
    { ko: "공간", en: "space" },
    { ko: "전시", en: "exhibit" },
  ] as const;

  const Experience: React.FC = () => {
    const [state, setState] = useState<PageState>(0);
  
    const onClick = (en: typeof division[number]["en"]) => {
      setState(
        en === "all" ? 0 : en === "museum" ? 1 : en === "space" ? 2 : 3
      );
    };

  return (
    <div className={styles["Experience"]}>
      <div className={styles["Experience-wrapper"]}>
        <div>
          <h2 className={styles["heading"]}>WHAT I DO</h2>
          <div className={styles["buttons"]}>
            {division.map((item, idx) => (
              <div
                className={
                  state === idx
                    ? styles["buttons-item_active"]
                    : styles["buttons-item"]
                }
                key={item.en}
                onClick={() => onClick(item.en)}
              >
                <div>{item.en}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
      {/* Cards 컴포넌트 Props 이름 pageState로 맞춤 */}
      <Cards pageState={state} />
    </div>
  );
};

export default Experience;